const raw = $input.first().json;
const b = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const val = (...keys) => { for (const k of keys) if (b[k] !== undefined && b[k] !== null) return String(b[k]).trim(); return ''; };
const strip = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const nombre = val('nombre','Nombre Completo').replace(/\s+/g,' ').slice(0,120);
const whatsapp = val('whatsapp','WhatsApp').replace(/[\s()-]/g,'').slice(0,25);
const correo = val('correo','Correo').toLowerCase().slice(0,254);
const fecha_preferida = val('fecha_preferida','Fecha preferida');
const hora_preferida = val('hora_preferida','Hora preferida');
const original = val('servicio','Servicio');
const servicio = strip(original);
const motivo = val('motivo','Motivo').slice(0,1500);
const usuario_whatsapp = val('usuario_whatsapp','Usuario Whatsapp ','Usuario Whatsapp').slice(0,120);
const origen = raw.body ? 'webhook' : 'formulario';
const faltantes = [];
for (const [k,v] of Object.entries({nombre,whatsapp,correo,fecha_preferida,hora_preferida,servicio})) if (!v) faltantes.push(k);
let motivo_rechazo = faltantes.length ? 'Faltan campos obligatorios: ' + faltantes.join(', ') + '.' : '';
if (!motivo_rechazo && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo)) motivo_rechazo='El correo no es válido.';
if (!motivo_rechazo && !/^\+?\d{7,15}$/.test(whatsapp)) motivo_rechazo='El WhatsApp debe contener entre 7 y 15 dígitos.';
const servicios = ['consulta medica','peluqueria','consulta veterinaria'];
if (!motivo_rechazo && !servicios.includes(servicio)) motivo_rechazo='Servicio no reconocido.';
const horas = ['08:00','09:00','10:00','11:00','13:00','14:00','15:00','16:00','17:00','18:00'];
if (!motivo_rechazo && !horas.includes(hora_preferida)) motivo_rechazo='Hora fuera del horario de atención.';
const d = /^\d{4}-\d{2}-\d{2}$/.test(fecha_preferida) ? DateTime.fromISO(fecha_preferida,{zone:'America/Bogota'}) : null;
if (!motivo_rechazo && (!d || !d.isValid || d.toISODate() !== fecha_preferida)) motivo_rechazo='Fecha inválida (AAAA-MM-DD).';
if (!motivo_rechazo) {
 const hoy = $now.setZone('America/Bogota').startOf('day');
 const dias = d.startOf('day').diff(hoy,'days').days;
 if (dias < 1 || dias > 7) motivo_rechazo='La fecha debe estar entre 1 y 7 días de anticipación.';
}
return [{json:{nombre,whatsapp,correo,fecha_preferida,hora_preferida,servicio,usuario_whatsapp,origen,motivo,valido:!motivo_rechazo,motivo_rechazo}}];

// Une los datos de la reserva con el resultado de la IA.
// La IA es un complemento: si falla o no hay motivo, la reserva sigue su curso normal.
const base = $('Preparar Solicitud').first().json;
const motivo = String(base.motivo ?? '').trim();
const recibido = $input.first().json;
let r = recibido.text ?? recibido.output ?? null;
if (typeof r === 'string') { try { r = JSON.parse(r); } catch { r = null; } }
const cats = ['rutina', 'urgente', 'otro'];
const ok = r !== null && typeof r === 'object' && !Array.isArray(r)
  && Object.keys(r).length === 3
  && cats.includes(r.categoria)
  && typeof r.resumen === 'string' && r.resumen.trim().length > 0 && r.resumen.length <= 500
  && typeof r.requiere_revision === 'boolean';
let ia;
if (!motivo) {
  ia = { motivo: '', motivo_categoria: 'sin_motivo', motivo_resumen: '', motivo_requiere_revision: false, motivo_estado: 'sin_motivo' };
} else if (ok) {
  ia = { motivo, motivo_categoria: r.categoria, motivo_resumen: r.resumen.trim(), motivo_requiere_revision: r.requiere_revision, motivo_estado: 'clasificado' };
} else {
  ia = { motivo, motivo_categoria: 'sin_clasificar', motivo_resumen: '', motivo_requiere_revision: true, motivo_estado: 'ia_no_disponible' };
}
return [{ json: { ...base, ...ia } }];

// Mismo cuerpo que la reserva: usa fecha_preferida y servicio. Misma regla de QuickBook: 1 a 7 días.
const b = $input.first().json.body ?? {};
const crudo = b.fecha_preferida ?? b.fecha;
const fecha = typeof crudo === 'string' ? crudo.trim() : '';
const servicio = typeof b.servicio === 'string' ? b.servicio.trim().slice(0, 60) : '';
let motivo = '';
const d = /^\d{4}-\d{2}-\d{2}$/.test(fecha) ? DateTime.fromISO(fecha) : null;
if (!d || !d.isValid) {
  motivo = 'La fecha debe tener formato AAAA-MM-DD.';
} else {
  const dias = d.startOf('day').diff($now.startOf('day'), 'days').days;
  if (dias < 1 || dias > 7) motivo = 'Solo se reserva entre 1 y 7 días de anticipación.';
}
return [{ json: { fecha, servicio, valida: motivo === '', motivo } }];

// La IA propone; este nodo verifica contra el calendario real antes de responder.
const v = $('Validar fecha').first().json;
const HORAS = ["08:00", "09:00", "10:00", "11:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00"];
const ZONA = 'America/Bogota';
const items = $input.all().map(i => i.json);

if (items.some(e => e && e.error)) {
  return [{ json: { estado: 'no_disponible', fecha: v.fecha, horas_disponibles: [], recomendadas: [], mensaje: 'No pude consultar el calendario en este momento. Intenta de nuevo en unos minutos.', verificado: false, ia: 'sin_resultado' } }];
}

const parse = (x) => {
  const s = x?.dateTime ?? x?.date ?? (typeof x === 'string' ? x : null);
  return s ? DateTime.fromISO(s, { setZone: true }).setZone(ZONA) : null;
};
const eventos = items.filter(e => e && e.start && e.status !== 'cancelled');
const libres = HORAS.filter(h => {
  const ini = DateTime.fromISO(v.fecha + 'T' + h, { zone: ZONA });
  const fin = ini.plus({ hours: 1 });
  return !eventos.some(e => {
    const a = parse(e.start), b = parse(e.end);
    return a && b && a < fin && b > ini;
  });
});

let ia = null;
try { ia = $('Agente de horarios').first().json.output; } catch (e) { ia = null; }
if (typeof ia === 'string') { try { ia = JSON.parse(ia); } catch { ia = null; } }
const iaValida = ia !== null && typeof ia === 'object'
  && Array.isArray(ia.horas_libres) && Array.isArray(ia.recomendadas) && typeof ia.mensaje === 'string';

const iaLibres = iaValida ? ia.horas_libres.filter(h => HORAS.includes(h)) : [];
const coincide = iaValida && iaLibres.length === libres.length && libres.every(h => iaLibres.includes(h));

let recomendadas = iaValida ? ia.recomendadas.filter(h => libres.includes(h)).slice(0, 3) : [];
if (recomendadas.length === 0) recomendadas = libres.slice(0, 3);

let mensaje;
if (libres.length === 0) {
  mensaje = 'No hay horarios disponibles para ese día. Prueba con otra fecha.';
} else if (iaValida && coincide && ia.mensaje.trim()) {
  mensaje = ia.mensaje.trim();
} else {
  mensaje = 'Horarios disponibles: ' + libres.join(', ') + '. Te sugerimos: ' + recomendadas.join(', ') + '.';
}

return [{ json: {
  estado: libres.length ? 'ok' : 'sin_horarios',
  fecha: v.fecha,
  horas_disponibles: libres,
  recomendadas,
  mensaje,
  verificado: true,
  ia: iaValida ? (coincide ? 'ok' : 'corregida_por_verificacion') : 'fallback_sin_ia'
} }];
